mapper.update:
UPDATE sys_user
username = #{username}, password_hash = #{password_hash}, real_name = #{real_name}, email = #{email}, phone = #{phone}, avatar = #{avatar}, is_active = #{is_active}, email_verified = #{email_verified}, phone_verified = #{phone_verified}, last_login_at = #{last_login_at}, last_login_ip = #{last_login_ip}, password_changed_at = #{password_changed_at}, deleted_at = #{deleted_at}, updated_at = NOW()
WHERE id = #{id}

mapper.select:
SELECT  FROM sys_user

    deleted_at IS NULL

        AND (username LIKE CONCAT('%',#{keyword},'%') OR real_name LIKE CONCAT('%',#{keyword},'%') OR email LIKE CONCAT('%',#{keyword},'%') OR phone LIKE CONCAT('%',#{keyword},'%'))


        AND EXISTS (
            SELECT 1 FROM sys_user_role ur
            JOIN sys_role r ON r.id = ur.role_id
            WHERE ur.user_id = sys_user.id AND r.role_code = #{user_type}
        )


        AND is_active = #{is_active}


ORDER BY created_at DESC
